queries.cql:
// CrowdStrike CQL for Salary Direct Deposit Rapid Cryptocurrency Conversion
// Repository: flame-banking-transaction-monitoring
// Correlates payroll deposit with crypto exchange transfer within 48h
(transaction_type="ACH_IN" AND transaction_category="payroll")
OR (outbound_type="crypto_exchange" OR outbound_type="p2p_crypto"
    OR outbound_type="wire_to_exchange")
| selfJoinFilter(account_id, where=[
    {transaction_type="ACH_IN" AND transaction_category="payroll"}
    {outbound_type="crypto_exchange" OR outbound_type="p2p_crypto"
      OR outbound_type="wire_to_exchange"}
  ])
| groupBy(account_id, function=[
    count(as=event_count),
    collect([transaction_type, outbound_type, transaction_amount, @timestamp])
  ], span=48h)
| event_count >= 2
